-- =============================================================================
-- Import CarTransit / VehnixAuto vers un nouveau projet Supabase
-- Généré depuis: db_cluster-24-08-2026@09-40-23.backup + migrations V1-V18
--
-- Usage:
--   1. Créer un nouveau projet Supabase
--   2. Ouvrir SQL Editor
--   3. Exécuter ce script en entier
--
-- Contenu:
--   - Structure complète (39 tables, migrations Flyway V1 -> V18)
--   - Données extraites du backup
--   - Historique Flyway synchronisé
-- =============================================================================

BEGIN;

SET session_replication_role = replica;

DO $$
DECLARE r RECORD;
BEGIN
  FOR r IN (
    SELECT tablename
    FROM pg_tables
    WHERE schemaname = 'public'
      AND tablename NOT IN ('schema_migrations')
  ) LOOP
    EXECUTE format('DROP TABLE IF EXISTS public.%I CASCADE', r.tablename);
  END LOOP;
END $$;

-- =============================================================================
-- STRUCTURE (Flyway V1 -> V18)
-- =============================================================================

-- V1__create_user_tables.sql
CREATE TABLE IF NOT EXISTS type_accounts (
    id          BIGSERIAL PRIMARY KEY,
    name        VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE IF NOT EXISTS users (
    id           BIGSERIAL PRIMARY KEY,
    password     VARCHAR(255),
    email        VARCHAR(255),
    username     VARCHAR(255),
    first_name   VARCHAR(100) NOT NULL,
    last_name    VARCHAR(100) NOT NULL,
    city         VARCHAR(100) NOT NULL,
    full_name    VARCHAR(255) NOT NULL,
    from_service VARCHAR(100),
    is_premium   BOOLEAN NOT NULL DEFAULT FALSE,
    is_certified BOOLEAN NOT NULL DEFAULT FALSE,
    is_lock      BOOLEAN NOT NULL DEFAULT FALSE,
    is_valid     BOOLEAN NOT NULL DEFAULT FALSE,
    phone        VARCHAR(50),
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_users_email ON users (email);
CREATE INDEX IF NOT EXISTS idx_users_phone ON users (phone);

CREATE TABLE IF NOT EXISTS accounts (
    id              BIGSERIAL PRIMARY KEY,
    name            VARCHAR(100) NOT NULL,
    type_account_id BIGINT NOT NULL REFERENCES type_accounts (id)
);

CREATE INDEX IF NOT EXISTS idx_accounts_type_account_id ON accounts (type_account_id);

CREATE TABLE IF NOT EXISTS account_users (
    id         BIGSERIAL PRIMARY KEY,
    account_id BIGINT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    user_id    BIGINT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    UNIQUE (account_id, user_id)
);

CREATE INDEX IF NOT EXISTS idx_account_users_user_id ON account_users (user_id);
CREATE INDEX IF NOT EXISTS idx_account_users_account_id ON account_users (account_id);

CREATE TABLE IF NOT EXISTS refresh_tokens (
    id           BIGSERIAL PRIMARY KEY,
    user_id      BIGINT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    expires_at   TIMESTAMP NOT NULL,
    hashed_token VARCHAR(512) NOT NULL,
    created_at   TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_refresh_tokens_user_id ON refresh_tokens (user_id);
CREATE INDEX IF NOT EXISTS idx_refresh_tokens_hashed_token ON refresh_tokens (hashed_token);

-- V2__create_car_tables.sql
CREATE TABLE IF NOT EXISTS car_models (
    id         BIGSERIAL PRIMARY KEY,
    brand      VARCHAR(100) NOT NULL,
    model      VARCHAR(100) NOT NULL,
    generation VARCHAR(100),
    body_type  VARCHAR(100),
    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    UNIQUE (brand, model)
);

CREATE INDEX IF NOT EXISTS idx_car_models_brand ON car_models (brand);

CREATE TABLE IF NOT EXISTS car_listings (
    id                    BIGSERIAL PRIMARY KEY,
    user_id               BIGINT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    car_model_id          BIGINT NOT NULL REFERENCES car_models (id),
    listing_type          VARCHAR(50) NOT NULL DEFAULT 'SALE',
    year                  INTEGER NOT NULL,
    is_electric           BOOLEAN NOT NULL DEFAULT FALSE,
    mileage_km            BIGINT NOT NULL DEFAULT 0,
    "condition"           VARCHAR(50) NOT NULL DEFAULT 'USED',
    plate_number          VARCHAR(50),
    color                 VARCHAR(50),
    seats                 INTEGER,
    price                 VARCHAR(50),
    rent_price_per_day    VARCHAR(50),
    exchange_description  TEXT,
    description           TEXT,
    city                  VARCHAR(100),
    country               VARCHAR(100) NOT NULL DEFAULT 'Democratic Republic of the Congo',
    status                VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
    created_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at            TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_car_listings_user_id ON car_listings (user_id);
CREATE INDEX IF NOT EXISTS idx_car_listings_car_model_id ON car_listings (car_model_id);
CREATE INDEX IF NOT EXISTS idx_car_listings_listing_type_status ON car_listings (listing_type, status);

CREATE TABLE IF NOT EXISTS car_images (
    id          BIGSERIAL PRIMARY KEY,
    car_id BIGINT REFERENCES car_listings (id) ON DELETE CASCADE,
    name        VARCHAR(255) NOT NULL,
    path        VARCHAR(500) NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_car_images_property_id ON car_images (car_id);

